param([Parameter(Mandatory)][ValidateSet('r453','r454')][string]$Stage,[Parameter(Mandatory)][string]$Revision)
$ErrorActionPreference='Stop'
$project=Split-Path -Parent $PSScriptRoot
. (Join-Path $PSScriptRoot 'evidence-json.ps1')
$logs=Join-Path $project 'logs\continuation-20261003'
function Pin($p){[ordered]@{path=$p;bytes=(Get-Item $p).Length;sha256=(Get-FileHash $p).Hash}}
function Check($p){if((Get-FileHash $p.path).Hash -ne $p.sha256 -or ($p.bytes -and (Get-Item $p.path).Length -ne $p.bytes)){throw ('Pin drift: '+$p.path)}}
$cp=Join-Path $logs "$Stage-candidate.json";$c=Get-Content $cp -Raw|ConvertFrom-Json;Check $c
foreach($p in $c.source_pins){Check $p;if((Get-FileHash $p.snapshot).Hash -ne $p.sha256){throw 'Current source snapshot drift'}}
$build=@(Get-Content (Join-Path $logs "$Revision-library-build.jsonl")|ForEach-Object{try{$_|ConvertFrom-Json}catch{}})
if(-not @($build|Where-Object{$_.reason -eq 'build-finished' -and $_.success}).Count){throw 'Production lib failed'}
$libs=@($build|Where-Object{$_.reason -eq 'compiler-artifact' -and $_.target.name -eq 'lito_modern'}|ForEach-Object{$_.filenames}|Where-Object{$_ -like '*.rlib'});if($libs.Count -ne 1){throw 'Lib count'}
$lib=Join-Path (Split-Path $c.path -Parent) "$Stage-production.rlib";if(Test-Path $lib){throw 'Already sealed'};[IO.File]::Copy($libs[0],$lib,$false);if((Get-FileHash $lib).Hash -ne (Get-FileHash $libs[0]).Hash){throw 'Library copy drift'};$c|Add-Member production_library (Pin $lib)
$test=Join-Path $logs "$Revision-consumer.stdout.log";if([IO.File]::ReadAllText($test) -notmatch '1 passed; 0 failed; 0 ignored;'){throw 'Focused test failed'}
$dp=Join-Path $logs $(if($Stage -eq 'r453'){'r453-roof-details.json'}else{'r454-layer8-details.json'});$d=Get-Content $dp -Raw|ConvertFrom-Json
if($d.runtime_inputs_observed -or $d.renderer_LOADED -or $d.GUI -ne 0){throw 'Runtime scope escalated'}
if($Stage -eq 'r453'){
 if($d.alias_keys -ne 61 -or $d.rows.Count -ne 8 -or $d.images.Count -ne 9 -or $d.rows[0].dispatch_ms -ne 1000 -or $d.rows[0].fresh_scheduler_ms -ne 1007 -or $d.rows[0].next_due_ms -ne 1057 -or $d.late_callback_catches_up -or !$d.restored_RGBA_equals_initial -or !$d.retire_cancels_pending -or !$d.retire_revokes_read -or $d.missing_move_cases -ne 6 -or $d.missing_callback_cases -ne 4){throw 'Roof chain differs'}
 $claims=@('Actual Native564 resident tile-pointer references reconstructed in 483770 depth order/newest-first equality;433210/432F70/4330D0 compare the loaded tile pointer without depth. 61cross-group alias keys retain one resident state; alias sample source groups share the same resident draw ID.','One actual source Layer5 kind0 group and exact whole-cell trigger are selected with explicit empty old set, local actor pointer, source-initialized actual flags0/0x100 and absence of dynamic cell entries. Source group IDs are array indices; serialized IDs never substitute.','48AFC0 old group reset/new target/write/read chain plus433210/432F70 Half transition:Source flags0 tiles31→27→23→19→0flags1; baseHalf0x100 tiles16→0flags0x101 at first callback;late due550 callback1000 advances once, fresh1007 reschedules1057. No elapsed catch-up.','433460 restore/write and4330D0 callbacks17→21→25→29→0 restore source flags0; baseHalf tiles17→0flags0x101 at first callback, preserving base half-opacity; final actual Native564 CPU pixels exactly equal initial. NineCPU images reviewed;RGB555 reference only.','Sixmissing move and fourmissing timer inputs refuse before state mutation. Retirement clears pending1550 and revokes callback/read/fullowner epoch substitution. This is a default-off finite conditional actor study, not observed native pointer allocation/live roof admission; other transitions/kinds/multigroup timers/Layer8 remain unqualified.')
 $historyNames=@('r447','r448','r449','r450','r451','r452');$sourceCount=522
}else{
 if($d.first_frame -ne 1 -or $d.next_continuation_executed -or !$d.retire_revokes_held_frame -or !$d.missing_inputs_preserve_pending -or $d.images.Count -lt 1){throw 'Layer8 chain differs'}
 $claims=@('One actual verified Native564 Layer8 FirePot38 source record is bound to the same immutable resource plan and offline owner. Actual row onlyaction3, type102=0, attr104=8, no101/105; no action0 pixels manufactured. Sprite38 dedicated Layer8 creation argument0xA retained as source fact. Runtime ID base30000 and Native class offset10000 remain explicit conditional values; no live actor allocation inferred.','One conditional source opcode32 action3 callback uses exact retained catalog11x2ticks/FPS24 and actual38-0SPR; reset0/increment1 selects first subframe1, returned83+2 with fresh scheduling clock. Scene raster uses the source attr8 Screen branch with explicit RGB555 floor reference, interleaving actual effect fragments at Layer8 absolute coordinates and static terrain; native external float-thunk rounding and RGB565 framebuffer parity remain unqualified.','12missing create and17missing callback inputs plus early/foreign revision preflight before pending callback consumption. Fresh500 creation schedule produces1084; callback1084 selectsframe1 and schedules1169 then stops; late1100/fresh1110 preview1195. Screen pixels differ from an unqualified Over comparison on the same selected SPR frame. Bound CPU frame verifies private model identity/fullowner/source plan; retirement cancels pending callbacks and revokes held frame reads. Natural lifetime/repeat/other events/default constructor/GUI remain unqualified.')
 $historyNames=@('r447','r448','r449','r450','r451','r452','r453');$sourceCount=524
}
foreach($p in $d.images){Check $p}
$ap=Join-Path $logs "$Stage-original-source-pins.json";$asm=Get-Content $ap -Raw|ConvertFrom-Json;Check $asm.original_disassembly;$text=[IO.File]::ReadAllText($asm.original_disassembly.path);foreach($p in $asm.files){Check $p;if(!$text.Contains([IO.File]::ReadAllText($p.path))){throw 'ASM not exact full function'}}
$sp=Join-Path $logs 'r439-appearance-snapshot.json';$snap=Get-Content $sp -Raw|ConvertFrom-Json;$mp=Join-Path $snap.candidate.root 'manifest.json';if((Get-FileHash $mp).Hash -ne $snap.candidate.manifest_sha256){throw 'Appearance manifest drift'}
$resources=@(foreach($name in $d.input_pins.PSObject.Properties.Name){$p=Pin (Join-Path $snap.candidate.root $name);if($p.sha256 -ne $d.input_pins.$name.sha256 -or $p.bytes -ne $d.input_pins.$name.bytes){throw 'Appearance input drift'};$p.relative_path=$name;$p});foreach($p in $d.extra_input_pins){Check $p}
$history=@(foreach($name in $historyNames){$p=Join-Path $logs "$name-candidate.json";$old=Get-Content $p -Raw|ConvertFrom-Json;Check $old;Check $old.production_library;foreach($source in $old.source_pins){if((Get-FileHash $source.snapshot).Hash -ne $source.sha256){throw 'Historical immutable source drift'}};Pin $p})
& (Join-Path $PSScriptRoot 'audit-continuation-source-scope.ps1');$scope=Get-Content (Join-Path $logs 'source-change-scope.json') -Raw|ConvertFrom-Json;if($scope.source_files -ne $sourceCount){throw 'Source scope differs'}
$scopePath=Join-Path (Split-Path $c.path -Parent) "source-change-scope-$sourceCount.json";[IO.File]::Copy((Join-Path $logs 'source-change-scope.json'),$scopePath,$false)
$c.validation='PASSED one new focused original-source conditional finite CPU state chain; current source/host/lib/resources frozen; live unqualified';Write-ModernEvidenceJson -Path $cp -Value $c
$result=Join-Path $logs "$Stage-finite-renderer-result.json";Write-ModernEvidenceJson -Path $result -Value ([ordered]@{state='PASSED_FINITE_CONDITIONAL_NATIVE_STATE_CHAIN';checked_at=[DateTimeOffset]::Now.ToString('o');candidate=$c;focused_passed=1;focused_failed=0;test=Pin $test;details=Pin $dp;ASM=Pin $ap;original_fragments=$asm.files.Count;selected_resources=$resources;extra_inputs=$d.extra_input_pins;claims=$claims;images=$d.images;visual_reviewed=$true;immutable_source_scope=Pin $scopePath;historical_preserved=$history;source_files=$sourceCount;renderer_LOADED=$false;GUI=0;original_BIN_executed=$false;overall_status='in_progress'})
$handoff=Join-Path $logs "$Stage-Native-state-chain-handoff.txt";[IO.File]::WriteAllText($handoff,($claims -join "`r`n")+"`r`nResult: $result`r`n$($c.source_pins.Count)source/$($asm.files.Count)fullASM/$($d.images.Count)CPU images. No old live rerun; R408 unchanged; all history snapshots retained. LOADEDfalse/GUI0/16of40.",[Text.UTF8Encoding]::new($false))
Write-ModernEvidenceJson -Path (Join-Path $logs "$Stage-final-verification.json") -Value ([ordered]@{result=Pin $result;candidate=Pin $cp;host=Pin $c.path;library=Pin $lib;details=Pin $dp;handoff=Pin $handoff;immutable_scope=Pin $scopePath;images=$d.images;visual_reviewed=$true;source_snapshots=$c.source_pins.Count;renderer_LOADED=$false;GUI=0})
$statusPath=Join-Path (Split-Path $project -Parent) '監製進度.json';$status=Get-Content $statusPath -Raw|ConvertFrom-Json;$status.updated_at=[DateTimeOffset]::Now.ToString('o');$status.phase="$Stage finite native state chain passed, remaining renderer branches in progress";$status.current_task="$Stage one new focused passed; $($claims -join ' ') $($c.source_pins.Count)source/$($asm.files.Count)fullASM/$($d.images.Count)CPU images pinned/reviewed;${sourceCount}sources/R408/history preserved. LOADEDfalse/GUI0/16of40.";$status|Add-Member "${Stage}_native_state_chain" (Pin $result) -Force;Write-ModernEvidenceJson -Path $statusPath -Value $status
Write-Output "$Stage sealed: $($c.source_pins.Count) source, $($d.images.Count) CPU images"
